export interface AnalysisToolParameter {
  symbol: string;
  label: string;
  unit?: string;
  /** null = no default; left empty, the server derives it genuinely */
  default: number | string | boolean | null;
  min?: number;
  max?: number;
  options?: string[];
  group?: string;
}

export type EquationComputeFn = (inputs: Record<string, number>) => {
  result: number;
  unit?: string;
  steps: string[];
};

export interface ToolOutput {
  id: string;
  label: string;
  type: 'scalar' | 'raster' | 'vector' | 'table';
  unit?: string;
  description?: string;
}

export interface AnalysisTool {
  id: number;
  name: string;
  toolName?: string;
  equation: string;
  shortDescription?: string;
  keywords?: string[];
  reference: string;
  paperUrl?: string;
  appliesTo: string;
  description?: string;
  inputs?: AnalysisToolParameter[];
  outputs?: ToolOutput[];
  analysisMeta?: AnalysisMeta;
  methodology?: string;
  paperSummary?: string;
  scientificConcept?: string;
  processingSteps?: string[];
  outputInterpretation?: string;
  assumptions?: string[];
  limitations?: string[];
  /** Expected deviation vs the cited paper / authoritative provider, stated at
   *  tool closing (validation rule 8). Optional: absent until a tool closes. */
  accuracy?: string;
}

/* ── Analytical Tool Metadata ── */

