export interface AnalysisMeta {
  needsTime: boolean;
  timeGranularity: TimeGranularity;
  studyAreaMode: StudyAreaMode;
  /** All study area modes scientifically valid for this tool */
  allowedStudyAreaModes: StudyAreaMode[];
  categoryFilters: CategoryFilterId[];
  autoDataSources: AutoDataSourceId[];
  /** Temporal controls relevant to this tool */
  temporalControls: TemporalControl[];
  /** Whether this tool uses forecast or historical data or both */
  temporalMode: 'historical' | 'forecast' | 'realtime' | 'both';
  /** Default aggregation period */
  defaultAggregation: AggregationPeriod;
  /** Scientific domain for data source selection */
  scientificDomain: ScientificDomain;
}

export type ScientificDomain =
  | 'atmospheric' | 'remote-sensing' | 'oceanography' | 'cryosphere'
  | 'air-quality' | 'soil-moisture' | 'hydrology' | 'vegetation'
  | 'radiation' | 'surface-temperature' | 'seismology' | 'space-weather'
  | 'geodesy' | 'geomorphology' | 'climate' | 'biosphere' | 'general';

