/** Default study-area mode for a tool = its first scientifically-valid mode
 *  (guaranteed to be inside allowedStudyAreaModes). */
function deriveStudyAreaMode(id: number): StudyAreaMode {
  return PER_TOOL_MODES[id]?.[0] ?? (TWO_POINTS.has(id) ? 'two-points' : 'point');
}

/** Returns the study area modes scientifically valid for a given tool, based on its methodology. */
function deriveAllowedStudyAreaModes(id: number, _domainNumber: number): StudyAreaMode[] {
  const modes = PER_TOOL_MODES[id];
  if (modes) return modes;

  // Fallback: if a tool is in TWO_POINTS, use two-points; otherwise default to point only
  if (TWO_POINTS.has(id)) return ['two-points'];
  return ['point'];
}

function deriveTemporalControls(id: number, domainNumber: number): TemporalControl[] {
  const tg = deriveTimeGranularity(id);
  if (tg === null) return [];

  const controls: TemporalControl[] = [];
  // Start/end date for all temporal tools
  controls.push('start-date');
  if (tg === 'range' || tg === 'multi-year') controls.push('end-date');

  // Domain-specific temporal controls
  const domainControls: Record<number, TemporalControl[]> = {
    1: ['time-zone', 'aggregation'],            // Atmospheric
    2: ['aggregation', 'time-interval'],         // Hydrology
    3: ['historical-forecast'],                   // Seismology
    4: ['time-zone'],                             // Remote sensing (acquisition time)
    7: ['aggregation', 'time-interval'],          // Biosphere
    8: ['aggregation'],                            // Agriculture
    9: ['aggregation', 'forecast-lead'],          // Air quality
    10: ['aggregation', 'time-interval'],         // Ocean
    11: ['time-zone', 'time-interval'],          // Coastal
    15: ['aggregation', 'historical-forecast'],  // Climate
    16: ['time-zone', 'aggregation', 'pressure-level' as unknown as TemporalControl], // Atmos dynamics
    17: ['time-interval'],                        // Cloud physics
    19: ['time-zone'],                            // Thermosphere
    23: ['historical-forecast', 'return-period' as unknown as TemporalControl], // Hazard
  };

  const extra = domainControls[domainNumber] ?? [];
  let result = Array.from(new Set([...controls, ...extra.filter(c => !c.includes('pressure') && !c.includes('return'))]));
  // Tide (14): harmonic prediction h(t) is evaluated at a specific time of day
  // (Pugh & Woodworth 2014). With a range we expose start/end time so the user
  // can pin/span the tidal curve — a bare date can't resolve the ~12.42 h M₂.
  if (id === 14) {
    result = Array.from(new Set([...result, 'start-time', 'end-time']));
  }
  return result;
}

function deriveTemporalMode(domainNumber: number): AnalysisMeta['temporalMode'] {
  const map: Record<number, AnalysisMeta['temporalMode']> = {
    1: 'both', 2: 'historical', 3: 'historical', 4: 'historical',
    5: 'historical', 6: 'both', 7: 'historical', 8: 'historical',
    9: 'forecast', 10: 'realtime', 11: 'realtime', 12: 'historical',
    13: 'historical', 14: 'historical', 15: 'historical', 16: 'both',
    17: 'realtime', 18: 'realtime', 19: 'realtime', 20: 'forecast',
    21: 'realtime', 22: 'historical', 23: 'historical', 24: 'realtime',
    25: 'realtime', 26: 'both',
  };
  return map[domainNumber] ?? 'historical';
}

function deriveDefaultAggregation(domainNumber: number): AggregationPeriod {
  const map: Record<number, AggregationPeriod> = {
    1: 'daily', 2: 'daily', 3: 'annual', 4: 'instant',
    5: 'annual', 6: 'daily', 7: 'daily', 8: 'daily',
    9: 'daily', 10: 'daily', 11: 'hourly', 12: 'annual',
    13: 'daily', 14: 'monthly', 15: 'monthly', 16: 'daily',
    17: 'instant', 18: 'instant', 19: 'instant', 20: 'instant',
    21: 'instant', 22: 'daily', 23: 'annual', 24: 'instant',
    25: 'instant', 26: 'instant',
  };
  return map[domainNumber] ?? 'daily';
}

function deriveTimeGranularity(id: number): TimeGranularity {
  if (NO_TIME_IDS.has(id)) return null;
  if (anyRange(id, MULTIYEAR)) return 'multi-year';
  if (anyRange(id, RANGE)) return 'range';
  if (anyRange(id, INSTANT)) return 'instant';
  return null;
}

function deriveCategoryFiltersForTool(toolId: number): CategoryFilterId[] {
  return TOOL_CATEGORY_FILTERS[toolId] ?? [];
}

