function deriveAutoDataSources(domainNumber: number): AutoDataSourceId[] {
  switch (domainNumber) {
    case 1: return ['era5', 'dem-elevation', 'landsat-lst', 'modis-lst', 'sentinel-3-slstr', 'open-meteo'];
    case 3: return ['usgs-earthquakes', 'tectonic-context', 'sentinel-1-insar'];
    case 4: return ['sentinel-2', 'modis-ndvi', 'modis-snow', 'viirs-fire', 'firms', 'landsat-lst', 'modis-lst', 'sentinel-3-slstr', 'dem-elevation', 'nsidc-seaice'];
    case 5: return ['dem-elevation', 'era5', 'gpm-imerg'];
    case 6: return ['smap-soil-moisture', 'smos-soil-moisture', 'soil-grids', 'dem-elevation'];
    case 7: return ['modis-ndvi', 'sentinel-2', 'era5', 'ceres-radiation'];
    case 8: return ['era5', 'modis-ndvi', 'sentinel-2', 'dem-elevation', 'smap-soil-moisture'];
    case 9: return ['cams-aerosol', 'sentinel-5p', 'openaq'];
    case 10: return ['copernicus-marine', 'aviso-altimetry', 'sea-surface-temperature', 'ndbc-buoys', 'wave-climate', 'gebco-bathymetry'];
    case 11: return ['copernicus-marine', 'wave-climate', 'ndbc-buoys', 'gebco-bathymetry'];
    case 12: return ['dem-elevation', 'hydrosheds', 'land-cover'];
    case 13: return ['dem-elevation', 'gebco-bathymetry'];
    case 14: return ['dem-elevation', 'modis-snow', 'nsidc-seaice', 'era5'];
    case 15: return ['era5', 'ceres-radiation', 'dem-elevation'];
    case 16: return ['era5', 'open-meteo'];
    case 17: return ['era5', 'goes-16', 'himawari-9'];
    case 18: return ['dem-elevation', 'noaa-swpc'];
    case 19: return ['noaa-swpc', 'era5'];
    case 20: return ['noaa-swpc', 'era5'];
    case 21: return ['noaa-swpc', 'era5'];
    case 22: return ['water-table-depth', 'soil-grids', 'smap-soil-moisture'];
    case 23: return ['worldpop', 'dem-elevation', 'usgs-earthquakes', 'gpm-imerg'];
    case 24: return ['era5'];
    default: return [];
  }
}

function deriveScientificDomain(domainNumber: number): ScientificDomain {
  const map: Record<number, ScientificDomain> = {
    1: 'atmospheric', 2: 'hydrology', 3: 'seismology', 4: 'remote-sensing',
    5: 'general', 6: 'soil-moisture', 7: 'vegetation', 8: 'vegetation',
    9: 'air-quality', 10: 'oceanography', 11: 'oceanography', 12: 'geomorphology',
    13: 'hydrology', 14: 'cryosphere', 15: 'climate', 16: 'atmospheric',
    17: 'atmospheric', 18: 'geodesy', 19: 'space-weather', 20: 'space-weather',
    21: 'space-weather', 22: 'hydrology', 23: 'general', 24: 'general',
    25: 'general', 26: 'general',
  };
  return map[domainNumber] ?? 'general';
}

function autoKeywords(domainName: string, name: string, appliesTo: string): string[] {
  const fromApplies = appliesTo.split(/[,;]/).map(s => s.trim().toLowerCase()).filter(Boolean);
  const fromDomain = domainName.toLowerCase();
  return Array.from(new Set([fromDomain, name.toLowerCase(), ...fromApplies]));
}

function autoDescription(appliesTo: string): string {
  return appliesTo;
}

function autoOutputs(_id: number): ToolOutput[] {
  return [{ id: 'primary', label: 'Result', type: 'scalar', description: 'Computed output value' }];
}

export function attachAnalysisMetadata(): void {
  PARTS.forEach(part =>
    part.domains.forEach(domain =>
      domain.tools.forEach(tool => {
        const tg = deriveTimeGranularity(tool.id);
        const domNum = domain.number;
        tool.analysisMeta = {
          needsTime: tg !== null,
          timeGranularity: tg,
          studyAreaMode: deriveStudyAreaMode(tool.id),
          allowedStudyAreaModes: deriveAllowedStudyAreaModes(tool.id, domNum),
          categoryFilters: deriveCategoryFiltersForTool(tool.id),
          autoDataSources: deriveAutoDataSources(domNum),
          temporalControls: (tool.id === 58 || tool.id === 60)
            ? deriveTemporalControls(tool.id, domNum).filter(c => c !== 'aggregation' && c !== 'time-interval')
            : deriveTemporalControls(tool.id, domNum),
          temporalMode: deriveTemporalMode(domNum),
          defaultAggregation: deriveDefaultAggregation(domNum),
          scientificDomain: deriveScientificDomain(domNum),
        };
        tool.shortDescription = tool.shortDescription || autoDescription(tool.appliesTo);
        tool.keywords = tool.keywords || autoKeywords(domain.name, tool.name, tool.appliesTo);
        tool.outputs = tool.outputs || autoOutputs(tool.id);
      })
    )
  );
}

